// Small real images as bytes (story 12), for tests that cannot read files
// (integration runs inside workerd; jsdom tests build File objects from them).
// The larger fixtures in tests/fixtures/images/ are used by e2e.

function b64(s: string): Uint8Array<ArrayBuffer> {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** 64x40 PNG (Chromium canvas). */
export const SMALL_PNG = b64('');
/** 64x40 JPEG. */
export const SMALL_JPEG = b64('');
/** 64x40 WebP. */
export const SMALL_WEBP = b64('');
/** 40x30 two-frame animated GIF (tests/fixtures/images/animated.gif). */
export const ANIMATED_GIF = b64('');
/** GIF87a header (enough for sniffing). */
export const GIF87A_HEAD = new TextEncoder().encode('GIF87a\x28\x00\x1e\x00');
/** SVG carrying a script (never accepted). */
export const SCRIPT_SVG = new TextEncoder().encode(
  '<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"><script>alert(1)</script></svg>',
);
/** A PDF, as if renamed to .png (never accepted). */
export const PDF_BYTES = new TextEncoder().encode('%PDF-1.4\n1 0 obj << /Type /Catalog >> endobj\ntrailer << /Root 1 0 R >>\n%%EOF\n');

/** A JPEG-signed body of exactly `size` bytes (the size-limit boundary). */
export function jpegOfSize(size: number): Uint8Array<ArrayBuffer> {
  const out = new Uint8Array(size);
  out.set(SMALL_JPEG.subarray(0, Math.min(size, SMALL_JPEG.length)));
  return out;
}
